3	import java.util.List;
4	import java.util.Map;
5	import org.springframework.context.annotation.Profile;
6	import org.springframework.jdbc.core.JdbcTemplate;
7	import org.springframework.web.bind.annotation.PostMapping;
8	import org.springframework.web.bind.annotation.RequestBody;
9	import org.springframework.web.bind.annotation.RequestMapping;
10	import org.springframework.web.bind.annotation.RestController;
11	
12	/**
13	 * Per-spec data setup for the harness (DESIGN.md §9). Profile-guarded so it exists ONLY under the
14	 * harness launch (bin/start sets spring.profiles.active=harness) — never in a real deploy. This is
15	 * APP CODE and EVOLVES with the schema (NOT pinned); a change that breaks a prior spec's seed is a
16	 * seed-path regression. Tests call these to ARRANGE data; they ASSERT only through the UI.
17	 */
18	@Profile("harness")
19	@RestController
20	@RequestMapping("/__test__")
21	public class TestSupportController {
22	
23	    private final Audit audit;
24	    private final JdbcTemplate jdbc;
25	
26	    public TestSupportController(Audit audit, JdbcTemplate jdbc) {
27	        this.audit = audit;
28	        this.jdbc = jdbc;
29	    }
30	
31	    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
32	    @PostMapping("/reset")
33	    public void reset() {
34	        audit.clear();
35	        // invoices references projects references clients, so H2 refuses to TRUNCATE a parent while
36	        // the FK exists — drop referential integrity for the duration, truncate all, then restore.
37	        jdbc.execute("SET REFERENTIAL_INTEGRITY FALSE");
38	        try {
39	            jdbc.execute("TRUNCATE TABLE notes RESTART IDENTITY");
40	            jdbc.execute("TRUNCATE TABLE project_tags RESTART IDENTITY");
41	            jdbc.execute("TRUNCATE TABLE tags RESTART IDENTITY");
42	            jdbc.execute("TRUNCATE TABLE tasks RESTART IDENTITY");
43	            jdbc.execute("TRUNCATE TABLE invoice_line_items RESTART IDENTITY");
44	            jdbc.execute("TRUNCATE TABLE invoices RESTART IDENTITY");
45	            jdbc.execute("TRUNCATE TABLE contacts RESTART IDENTITY");
46	            jdbc.execute("TRUNCATE TABLE projects RESTART IDENTITY");
47	            jdbc.execute("TRUNCATE TABLE clients RESTART IDENTITY");
48	        } finally {
49	            jdbc.execute("SET REFERENTIAL_INTEGRITY TRUE");
50	        }
51	    }
52	
53	    /** Insert the fixture a spec needs; the payload shape evolves with the schema. */
54	    @PostMapping("/seed")
55	    @SuppressWarnings("unchecked")
56	    public void seed(@RequestBody Map<String, Object> fixture) {
57	        List<Map<String, Object>> clients =
58	                (List<Map<String, Object>>) fixture.getOrDefault("clients", List.of());
59	        // Explicit ids from the fixture (the spec asserts rows by these ids), via JdbcTemplate.
60	        for (Map<String, Object> c : clients) {
61	            jdbc.update("INSERT INTO clients (id, name, email) VALUES (?, ?, ?)",
62	                    ((Number) c.get("id")).longValue(), c.get("name"), c.get("email"));
63	        }
64	        List<Map<String, Object>> projects =
65	                (List<Map<String, Object>>) fixture.getOrDefault("projects", List.of());
66	        for (Map<String, Object> p : projects) {
67	            jdbc.update("INSERT INTO projects (id, name, client_id) VALUES (?, ?, ?)",
68	                    ((Number) p.get("id")).longValue(), p.get("name"),
69	                    ((Number) p.get("clientId")).longValue());
70	        }
71	        List<Map<String, Object>> contacts =
72	                (List<Map<String, Object>>) fixture.getOrDefault("contacts", List.of());
73	        for (Map<String, Object> c : contacts) {
74	            jdbc.update(
75	                    "INSERT INTO contacts (id, name, email, contact_role, client_id)"
76	                            + " VALUES (?, ?, ?, ?, ?)",
77	                    ((Number) c.get("id")).longValue(), c.get("name"), c.get("email"),
78	                    c.get("role"), ((Number) c.get("clientId")).longValue());
79	        }
80	        List<Map<String, Object>> invoices =
81	                (List<Map<String, Object>>) fixture.getOrDefault("invoices", List.of());
